/* @lc app=leetcode id=3225 lang=kotlin */ class Solution { fun maximumScore(grid: Array<IntArray>): Long = grid.size.let { n -> (0 until n).fold(Array(n + 1) { p -> LongArray(n + 1) { if (p == 0) 0L else Long.MIN_VALUE / 4 } }) { dp, j -> grid.indices.runningFold(0L) { s, r -> s + grid[r][j] }.let { pre -> Array(n + 1) { h -> (0..n).map { dp[it][h] }.let { col -> col.runningFold(Long.MIN_VALUE / 4) { m, v -> maxOf(m, v) }.drop(1).let { pm -> (n downTo 0).runningFold(Long.MIN_VALUE / 4) { m, p -> maxOf(m, col[p] + maxOf(0L, pre[p] - pre[h])) }.let { sm -> LongArray(n + 1) { nx -> if (j == n - 1 && nx != 0) Long.MIN_VALUE / 4 else maxOf(pm[nx] + maxOf(0L, pre[nx] - pre[h]), sm[n - nx]) } } } } } } }.maxOf { it.max() } } }